import fs from 'node:fs';
const dir='artifacts/partner-sales-audit-20261016/';const read=k=>JSON.parse(fs.readFileSync(dir+k+'.json'));const leads=read('leads'),contacts=read('contacts'),touches=read('touches'),sms=read('sms'),calls=read('calls'),referrals=read('referrals'),tasks=read('tasks');
const norm=s=>String(s||'').replace(/\D/g,'').slice(-10);const cm=new Map(contacts.map(c=>[c.id,c]));
const linkedPhones=new Set(leads.filter(l=>l.data?.partnerReferralContactId||l.data?.relationshipContactId||referrals.some(r=>r.crm_lead_id===l.id)).map(l=>norm(l.data.phone)).filter(p=>p.length===10));
const out=[];for(const l of leads){const d=l.data||{},r=referrals.filter(r=>r.crm_lead_id===l.id);const ids=[d.partnerReferralContactId,d.relationshipContactId,d.partnerContactId,d.partnerHandoff?.contactId,...r.map(r=>r.contact_id)].filter(Boolean);const phone=norm(d.phone);const peers=contacts.filter(c=>phone.length===10&&norm(c.phone)===phone);const explicit=ids.length||/partner|relationship/.test(d.source||'');const recent=String(d.createdAt||'')>='2026-09-16';if(!recent||(!explicit&&!peers.length&&!linkedPhones.has(phone)&&!/referral/i.test(d.source||'')))continue;const cs=[...new Map([...ids.map(id=>cm.get(id)),...peers].filter(Boolean).map(c=>[c.id,c])).values()];const ts=touches.filter(t=>cs.some(c=>c.id===t.contact_id)).sort((a,b)=>a.created_at.localeCompare(b.created_at));const sm=sms.filter(s=>s.lead_id===l.id||(phone.length===10&&[norm(s.from_number),norm(s.to_number)].includes(phone)));const cr=calls.filter(c=>c.lead_id===l.id||(phone.length===10&&norm(c.phone_number)===phone));const logs=d.callLogs||[];out.push({id:l.id,deleted:l.deleted,name:d.name,created:d.createdAt,stage:d.stage,source:d.source,kind:d.leadKind,move:d.moveDate,assigned:d.assignedRepName||d.assignedRep,explicit:!!explicit,contacts:cs.map(c=>({id:c.id,name:c.name,category:c.category})),data:d,touches:ts,sms:sm,calls:cr,logs,tasks:tasks.filter(t=>[l.id,...cs.map(c=>c.id)].includes(t.related_id))});}
fs.writeFileSync(dir+'joined.json',JSON.stringify(out));
for(const x of out)console.log(JSON.stringify({id:x.id,name:x.name,created:x.created,stage:x.stage,move:x.move,deleted:x.deleted,explicit:x.explicit,assigned:x.assigned,contacts:x.contacts.map(c=>c.name),sms:x.sms.length,calls:x.calls.length,logs:x.logs.length,summary:x.data.partnerLeadSummary,notes:!x.data.partnerLeadSummary?x.data.notes?.slice(0,300):undefined}));
console.log('COUNT',out.length);
